    csrw_ss(ACC_S_STRIDE_WRITER_0_0, 8);
    csrw_ss(ACC_T_BOUND_WRITER_0_0, 2);
    csrw_ss(ACC_T_STRIDE_WRITER_0_0, 32);
#ifdef FORGE_QUIET
    write_csr(0x7c5, 4);  // acc config acc
#endif  // FORGE_QUIET
    csrw_ss(ACC_RW_JOBS, 2);
